"""Expanded networks, SCC constraints and shortest-path DAG contributions."""
from nowcoder_editorials import CONTENT, add, read, reviewed_clone
from nowcoder_dsu_support import DSU
from nowcoder_graph_support import DIJKSTRA, SCC


def run():
    existing = read(CONTENT / 'reviewed.json')
    def put(n, *args, **kwargs):
        if f'nowcoder-global::{n}' not in existing:
            add(n, *args, **kwargs)
    put(251589, 1900, ['Dijkstra', '虚拟结点'], '每个地点集合内任意两点间走一次耗时t，两人从1、n出发，求最早在哪些地点会合。',
        '每个集合建虚拟点，成员地点→虚拟点权t，虚拟点→成员地点权0。这样集合内任意两点费用恰为t，且只需O(集合大小)条边，不会两两连成平方边数。分别从1和n做Dijkstra。若选择地点v会合，两人同时出发并允许等待，时间为max(d1[v],dn[v])，在所有原地点中取最小并输出全部最优地点。虚拟点只是建图辅助，不是可会合的地点。',
        r'''int tests; cin >> tests; for (int tc = 1; tc <= tests; tc++) { int n,m; cin >> n >> m; vector<vector<pair<int,long long>>> graph(n + m); for (int i = 0; i < m; i++) { long long time; int size; cin >> time >> size; while (size--) { int u; cin >> u; --u; graph[u].push_back({n + i,time}); graph[n + i].push_back({u,0}); } } auto a = dijkstra(graph,0), b = dijkstra(graph,n - 1); long long best = 1LL << 60; for (int u = 0; u < n; u++) best = min(best,max(a[u],b[u])); cout << "Case #" << tc << ": "; if (best == (1LL << 60)) { cout << "Evil John\n"; continue; } cout << best << '\n'; bool first = true; for (int u = 0; u < n; u++) if (max(a[u],b[u]) == best) { if (!first) cout << ' '; first = false; cout << u + 1; } cout << '\n'; }''',
        '不能把两人距离相加再除二，题目只能在原地点会合。实际输出带Case #编号，依原样例格式。', declarations=DIJKSTRA,
        complexity=r'总集合元素数 $L$，时间 $O((n+m+L)\log(n+m))$，空间 $O(n+m+L)$。')
    put(16697, 1800, ['Dijkstra', '几何建图'], '各城四机场构成矩形，城内铁路与跨城飞机单价不同，从起点城任意机场到终点城任意机场求最便宜。',
        '每城已给三个矩形顶点，找到三点中直角点p，其余为q、r，则第四点为q+r−p。直角用点积等于0判定，整数坐标可精确判断。将每个机场当结点，同城两机场边费为欧氏距离乘本城铁路单价，异城边费为距离乘飞机单价。\n\n最多400点，直接用稠密Dijkstra，初始起点城四机场距离均为0。每次选最小未定点后，枚举全部机场计算直达费用并松弛，允许经过第三座城市或多次换乘。终点四机场取最小，保留一位小数。',
        r'''int tests; cin >> tests; while (tests--) { int cities, start, target; long double flight; cin >> cities >> flight >> start >> target; --start; --target; vector<array<long long,2>> point(4 * cities); vector<long double> rail(cities); for (int city = 0; city < cities; city++) { array<array<long long,2>,3> p; for (auto &v : p) cin >> v[0] >> v[1]; cin >> rail[city]; int right = 0; for (int i = 0; i < 3; i++) { int j = (i + 1) % 3, k = (i + 2) % 3; __int128 dot = (__int128)(p[j][0] - p[i][0]) * (p[k][0] - p[i][0]) + (__int128)(p[j][1] - p[i][1]) * (p[k][1] - p[i][1]); if (dot == 0) right = i; } for (int i = 0; i < 3; i++) point[4 * city + i] = p[i]; for (int axis = 0; axis < 2; axis++) point[4 * city + 3][axis] = p[(right + 1) % 3][axis] + p[(right + 2) % 3][axis] - p[right][axis]; } int n = 4 * cities; vector<long double> d(n,1e100L); vector<bool> done(n); for (int i = 0; i < 4; i++) d[4 * start + i] = 0; for (int step = 0; step < n; step++) { int u = -1; for (int v = 0; v < n; v++) if (!done[v] && (u == -1 || d[v] < d[u])) u = v; done[u] = true; for (int v = 0; v < n; v++) if (!done[v]) { long double dx = (long double)point[u][0] - point[v][0], dy = (long double)point[u][1] - point[v][1]; long double cost = hypotl(dx,dy) * (u / 4 == v / 4 ? rail[u / 4] : flight); d[v] = min(d[v],d[u] + cost); } } cout << fixed << setprecision(1) << *min_element(d.begin() + 4 * target,d.begin() + 4 * target + 4) << '\n'; }''',
        '三个输入机场的顺序任意，不能把第一个直接认作直角点。同城铁路也可能通过别城绕行更便宜，完整图最短路会自动比较。',
        complexity=r'每组机场数 $V=4S$，时间 $O(V^2)$，空间 $O(V)$。', floating_output=True)
    put(16611, 1900, ['强连通分量', '拓扑排序', '动态规划'], '从1走到n，可重复经过城市，至多买卖一次，最大化卖价减买价。',
        '将有向图缩成强连通分量DAG。每个分量内可以任意来回，记录最低、最高商品价。拓扑传播buy[c]：从1到该分量的所有路线中，能遇到的最低买价，进入分量时与该分量最低价取小。\n\n再在缩点反图从n的分量搜索，标记能继续到终点的分量。对既可由1到达又能到n的每个分量，尝试在此分量最高价处卖出，收益maxPrice[c]−buy[c]，全局至少0。SCC内能先到最低价点再到最高价点，所以使用分量极值是可实现的，重复经过城市的情况也被包含。',
        r'''int n,m; cin >> n >> m; vector<int> price(n); for (int &x : price) cin >> x; vector<vector<int>> graph(n), reverse(n); auto addEdge = [&](int a, int b) { graph[a].push_back(b); reverse[b].push_back(a); }; while (m--) { int a,b,type; cin >> a >> b >> type; --a; --b; addEdge(a,b); if (type == 2) addEdge(b,a); } auto [count,component] = components(graph,reverse); vector<int> low(count,101), high(count), degree(count); vector<vector<int>> dag(count), back(count); for (int u = 0; u < n; u++) { int a = component[u]; low[a] = min(low[a],price[u]); high[a] = max(high[a],price[u]); for (int v : graph[u]) if (a != component[v]) { dag[a].push_back(component[v]); back[component[v]].push_back(a); degree[component[v]]++; } } vector<bool> reachesTarget(count); vector<int> queue{component[n - 1]}; reachesTarget[queue[0]] = true; for (size_t h = 0; h < queue.size(); h++) for (int v : back[queue[h]]) if (!reachesTarget[v]) { reachesTarget[v] = true; queue.push_back(v); } queue.clear(); for (int c = 0; c < count; c++) if (!degree[c]) queue.push_back(c); vector<int> buy(count,101); buy[component[0]] = low[component[0]]; int answer = 0; for (size_t h = 0; h < queue.size(); h++) { int u = queue[h]; if (buy[u] != 101 && reachesTarget[u]) answer = max(answer,high[u] - buy[u]); for (int v : dag[u]) { if (buy[u] != 101) buy[v] = min(buy[v],min(buy[u],low[v])); if (--degree[v] == 0) queue.push_back(v); } } cout << answer;''',
        '买卖点必须按可行路线先后到达，不能只在所有可达城市里取全局最低最高价。卖出后还必须能到n。强连通搜索用显式栈处理长链。', declarations=SCC,
        complexity=r'时间、空间均为 $O(n+m)$。')
    if 'nowcoder-global::50379' not in existing:
        reviewed_clone(50379, 16611, '完整核对两道NOIP2009最优贸易，十万点五十万条混合单/双向边、价1到100、起1终n且至多一次交易，完全一致。')
    put(50381, 2000, ['Dijkstra', '拓扑排序', '连通分量'], '非负双向道路与可为负的单向航线，航线不会处于回路中，求从S到各点最短费用。',
        '先只按道路划分连通块。任何航线都连两个不同道路块，否则道路可从终点回起点，违反保证；所有块之间的航线组成DAG。按块拓扑处理：一个块所有入航线已处理后，将块内所有已有有限距离的点一起放入堆，在仅道路的块内跑多源Dijkstra。道路非负，因此这一阶段正确。\n\n块内距离确定后，再逐条松弛出航线，允许负费用，并减少目标块入度；入度归零的块入队。不可达块也要完成拓扑出边计数，否则会卡住后继。这样负边只在DAG层传播，不会进入Dijkstra堆。',
        r'''int n,r,p,start; cin >> n >> r >> p >> start; --start; vector<vector<pair<int,long long>>> road(n); DSU dsu(n); while (r--) { int a,b; long long w; cin >> a >> b >> w; --a; --b; road[a].push_back({b,w}); road[b].push_back({a,w}); dsu.unite(a,b); } vector<vector<int>> members(n); for (int u = 0; u < n; u++) members[dsu.find(u)].push_back(u); struct Flight { int from,to; long long cost; }; vector<vector<Flight>> flight(n); vector<int> degree(n); while (p--) { int a,b; long long w; cin >> a >> b >> w; --a; --b; flight[dsu.find(a)].push_back({a,b,w}); degree[dsu.find(b)]++; } const long long inf = 1LL << 60; vector<long long> distance(n,inf); distance[start] = 0; vector<int> queue; for (int c = 0; c < n; c++) if (!members[c].empty() && !degree[c]) queue.push_back(c);
        for (size_t h = 0; h < queue.size(); h++) { int component = queue[h]; priority_queue<pair<long long,int>,vector<pair<long long,int>>,greater<pair<long long,int>>> heap; for (int u : members[component]) if (distance[u] != inf) heap.push({distance[u],u}); while (!heap.empty()) { auto [cost,u] = heap.top(); heap.pop(); if (cost != distance[u]) continue; for (auto [v,w] : road[u]) if (distance[v] > cost + w) { distance[v] = cost + w; heap.push({distance[v],v}); } } for (auto e : flight[component]) { if (distance[e.from] != inf) distance[e.to] = min(distance[e.to],distance[e.from] + e.cost); int target = dsu.find(e.to); if (--degree[target] == 0) queue.push_back(target); } } for (long long d : distance) { if (d == inf) cout << "NO PATH\n"; else cout << d << '\n'; }''',
        '有负航线，不能对整图直接Dijkstra。块内起点可能不止一个，且带着不同的已有费用，必须全部入堆。', declarations=DSU,
        complexity=r'时间 $O((N+R)\log N+P+(N+R)\alpha(N))$，空间 $O(N+R+P)$。')
    put(20568, 2200, ['最小生成树', '分层贪心', '可达性'], '只能沿不升高的边滑行，回到历史点免费，先最大化可达景点，再最小化实际滑行总长。',
        '先将每条轨道按高到低定向，等高则双向，从1搜索得到全部可达点；免费回溯允许遍历一个根连通的滑行树，因此最多访问全部这些点。\n\n按高度从高到低建立它们的最小进入树。处理高度h时，已处理的更高可达点均已连到起点，可视为一个超级根。候选边包括高处到h的边及h内部的等高边，这是一个无向MST子问题：在同高度连通部分内，边可任选方向，高到低边总能作向下入口。按“较低端高度递减、边长递增”排序，Kruskal依次连不同块，就等价于逐高度求这个局部MST。每层选到可达点与已有根连通，局部最小费用可独立相加；每条可达点的进入边至少要付一次，故下界达到。',
        r'''int n,m; cin >> n >> m; vector<long long> height(n); for (auto &x : height) cin >> x; struct Edge { int high,low; long long w; }; vector<Edge> edges(m); vector<vector<int>> downhill(n); for (auto &e : edges) { cin >> e.high >> e.low >> e.w; --e.high; --e.low; if (height[e.high] < height[e.low]) swap(e.high,e.low); downhill[e.high].push_back(e.low); if (height[e.high] == height[e.low]) downhill[e.low].push_back(e.high); } vector<bool> reachable(n); vector<int> queue{0}; reachable[0] = true; for (size_t h = 0; h < queue.size(); h++) for (int v : downhill[queue[h]]) if (!reachable[v]) { reachable[v] = true; queue.push_back(v); } edges.erase(remove_if(edges.begin(),edges.end(),[&](auto e) { return !reachable[e.high] || !reachable[e.low]; }),edges.end()); sort(edges.begin(),edges.end(),[&](auto a, auto b) { if (height[a.low] != height[b.low]) return height[a.low] > height[b.low]; return a.w < b.w; }); DSU dsu(n); long long answer = 0; for (auto e : edges) if (dsu.unite(e.high,e.low)) answer += e.w; cout << queue.size() << ' ' << answer;''',
        '不能全图只按边长普通Kruskal，否则树的边方向可能使景点无法从1到达。首先筛掉不可达点，高度层之间保持从高到低。', declarations=DSU,
        complexity=r'时间 $O(m\log m+(n+m)\alpha(n))$，空间 $O(n+m)$。')
    put(19964, 1500, ['最小生成树', '最小瓶颈'], '不同猴子有不同跳距，判断有多少能在全部树冠间来回觅食。',
        '跳距d可觅食全部树，等价于只保留长度≤d的树冠连边后图连通。完整欧氏图的任一最小生成树，其最大边长是所有生成树中最小的瓶颈；故只需求MST的最大边，再比较每只猴子跳距。N≤1000，使用稠密Prim，不显式存百万条边。全程比较平方距离，无需浮点开根。',
        r'''int m; cin >> m; vector<long long> jump(m); for (auto &x : jump) cin >> x; int n; cin >> n; vector<array<long long,2>> point(n); for (auto &p : point) cin >> p[0] >> p[1]; vector<long long> best(n,1LL << 60); vector<bool> used(n); best[0] = 0; long long threshold = 0; for (int step = 0; step < n; step++) { int u = -1; for (int v = 0; v < n; v++) if (!used[v] && (u == -1 || best[v] < best[u])) u = v; used[u] = true; threshold = max(threshold,best[u]); for (int v = 0; v < n; v++) if (!used[v]) { long long dx = point[u][0] - point[v][0], dy = point[u][1] - point[v][1]; best[v] = min(best[v],dx * dx + dy * dy); } } int answer = 0; for (long long d : jump) answer += d * d >= threshold; cout << answer;''',
        '只要求可经中间树冠到所有树，不要求一跳到任意树。比较MST最大边，不是MST总长或最远两树距离。', complexity=r'时间 $O(N^2+M)$，空间 $O(N+M)$。')
    put(50390, 1900, ['差分约束', 'Bellman-Ford'], '按编号不下降排队，朋友距离有上限、敌人距离有下限，求首尾最大间距或矛盾、无界。',
        '设位置x1≤…≤xN。统一写成x[v]≤x[u]+w：顺序给i+1→i权0；朋友A<B要求x[B]−x[A]≤D，连A→B权D；敌人要求x[B]−x[A]≥D，连B→A权−D。原输入描述把差值顺序写反，按“距离”和样例中的正间距理解为后者减前者。\n\n先把所有点距离置0，Bellman-Ford检查全图负环，有则无任何合法位置，输出−1。可行后，从1重新求最短路；每条1到N的路径都给首尾差一个上界，最紧者是最短距离，并可由差分约束势函数达到。若N不可达，则没有有限上界，输出−2；否则输出最短距离。',
        r'''int n,close,far; cin >> n >> close >> far; struct Edge { int a,b; long long w; }; vector<Edge> edges; for (int i = 1; i < n; i++) edges.push_back({i,i - 1,0}); while (close--) { int a,b; long long d; cin >> a >> b >> d; edges.push_back({a - 1,b - 1,d}); } while (far--) { int a,b; long long d; cin >> a >> b >> d; edges.push_back({b - 1,a - 1,-d}); } vector<long long> d(n); for (int round = 1; round <= n; round++) { bool changed = false; for (auto e : edges) if (d[e.b] > d[e.a] + e.w) { d[e.b] = d[e.a] + e.w; changed = true; } if (!changed) break; if (round == n) { cout << -1; return 0; } } const long long inf = 1LL << 60; fill(d.begin(),d.end(),inf); d[0] = 0; for (int round = 1; round < n; round++) { bool changed = false; for (auto e : edges) if (d[e.a] != inf && d[e.b] > d[e.a] + e.w) { d[e.b] = d[e.a] + e.w; changed = true; } if (!changed) break; } cout << (d[n - 1] == inf ? -2 : d[n - 1]);''',
        '必须先全图判可行性，不能只判从1可达的负环。目标虽是最大距离，差分约束的上界模型用最短路。', complexity=r'时间 $O(N(N+M_L+M_D))$，空间 $O(N+M_L+M_D)$。',
        cases=[{'input':'2 1 1\n1 2 1\n1 2 2','output':'-1'},{'input':'3 1 1\n1 2 5\n2 3 1','output':'-2'}])
    put(20284, 1900, ['强连通分量', '差分约束', '拓扑排序'], '每人至少一个糖果，满足相等及严格、非严格比较关系，最小化总数。',
        '统一为lower[v]≥lower[u]+w，w只能0或1。相等连两条0边，A<B连A→B权1，A≥B连B→A权0，A>B连B→A权1，A≤B连A→B权0。非负边图中，矛盾等价于某个有向环包含1边；缩SCC后，只要内部有1边就输出−1。\n\n其余SCC内全为0，所有人可取同一个最小值。缩点DAG上所有分量初值1，拓扑求最长下界d[v]=max(d[v],d[u]+w)。这些值同时达到全部约束的逐点最小值，因此按每个分量人数累加就是最小总糖果数。',
        r'''int n,k; cin >> n >> k; struct Edge { int a,b,w; }; vector<Edge> edges; vector<vector<int>> graph(n), reverse(n); auto addEdge = [&](int a, int b, int w) { edges.push_back({a,b,w}); graph[a].push_back(b); reverse[b].push_back(a); }; while (k--) { int type,a,b; cin >> type >> a >> b; --a; --b; if (type == 1) { addEdge(a,b,0); addEdge(b,a,0); } else if (type == 2) addEdge(a,b,1); else if (type == 3) addEdge(b,a,0); else if (type == 4) addEdge(b,a,1); else addEdge(a,b,0); } auto [count,component] = components(graph,reverse); vector<vector<pair<int,int>>> dag(count); vector<int> degree(count); for (auto e : edges) { int a = component[e.a], b = component[e.b]; if (a == b) { if (e.w) { cout << -1; return 0; } } else { dag[a].push_back({b,e.w}); degree[b]++; } } vector<int> queue; vector<long long> value(count,1); for (int c = 0; c < count; c++) if (!degree[c]) queue.push_back(c); for (size_t h = 0; h < queue.size(); h++) { int u = queue[h]; for (auto [v,w] : dag[u]) { value[v] = max(value[v],value[u] + w); if (--degree[v] == 0) queue.push_back(v); } } long long answer = 0; for (int u = 0; u < n; u++) answer += value[component[u]]; cout << answer;''',
        '比较是整数，严格少于至少差1。相同编号的严格比较会形成1权自环，必须判无解。总数可能超过32位。', declarations=SCC,
        complexity=r'时间、空间均为 $O(N+K)$。')
    put(19987, 2200, ['Dijkstra', '最短路计数', '有向无环图'], '对每条有向边统计它经过多少条任意起终点的不同最短路，模十亿加七。',
        '枚举起点s做Dijkstra，取出满足d[u]+w=d[v]的最短路DAG。正边权保证距离递增是拓扑序。prefix[u]为从s到u的最短路数，按正序相加；suffix[u]为从u出发、沿这个DAG到任意终点的路径数，包含终点就是u的空后缀，故suffix[u]=1+Σsuffix[v]，反序计算。\n\n对DAG中的每条原边u→v，经过它且起点为s的最短路有prefix[u]*suffix[v]条：任选到u的最短前缀、这条边、从v起的后缀，因DAG不会重复点且整路均在最短路结构中，一一对应。对所有s累加。重边按不同原道路分别保留，符合道路序列区分路径的定义。',
        r'''int n,m; cin >> n >> m; struct Edge { int from,to,w; }; vector<Edge> edges(m); vector<vector<int>> graph(n); for (int i = 0; i < m; i++) { auto &e = edges[i]; cin >> e.from >> e.to >> e.w; --e.from; --e.to; graph[e.from].push_back(i); } const long long mod = 1000000007, inf = 1LL << 60; vector<long long> answer(m); for (int start = 0; start < n; start++) { vector<long long> distance(n,inf), prefix(n), suffix(n,1); vector<int> order; priority_queue<pair<long long,int>,vector<pair<long long,int>>,greater<pair<long long,int>>> heap; distance[start] = 0; heap.push({0,start}); while (!heap.empty()) { auto [cost,u] = heap.top(); heap.pop(); if (cost != distance[u]) continue; order.push_back(u); for (int id : graph[u]) { auto e = edges[id]; if (distance[e.to] > cost + e.w) { distance[e.to] = cost + e.w; heap.push({distance[e.to],e.to}); } } } prefix[start] = 1; for (int u : order) for (int id : graph[u]) { auto e = edges[id]; if (distance[u] + e.w == distance[e.to]) prefix[e.to] = (prefix[e.to] + prefix[u]) % mod; } for (int i = (int)order.size() - 1; i >= 0; i--) { int u = order[i]; for (int id : graph[u]) { auto e = edges[id]; if (distance[u] + e.w == distance[e.to]) { suffix[u] = (suffix[u] + suffix[e.to]) % mod; answer[id] = (answer[id] + prefix[u] * suffix[e.to]) % mod; } } } } for (long long x : answer) cout << x << '\n';''',
        'suffix必须加1，表示在当前点结束，不然会漏掉以v为终点的路径。只计算从当前s可达的DAG结点，边不是无向的。',
        complexity=r'时间 $O(n(n+m)\log n)$，空间 $O(n+m)$。')


if __name__ == '__main__':
    run()
